//Whole44fcc0 BUILD-completion branch. Render/path-result/UI/CRT are explicit
//recorded leaves.64-slot allocator and writer/tail instructions execute.
import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZV43TrailJobBirthOracle2 extends GhidraScript{
 static final long U=0x1800000L,B=U+256,W=U+512,G=U+768,J=0x62d5f8L,H=0x5ba0a8L,S=0x7fff0000L,RET=0x12345000L,RAND=RET+4096;
 long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}void set(byte[]b,int a,int n,long v){for(int i=0;i<n;i++)b[a+i]=(byte)(v>>(8*i));}int hash(byte[]b){int h=0x811c9dc5;for(byte v:b)h=(h^(v&255))*16777619;return h;}String hex(byte[]b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format("%02x",v&255));return s.toString();}
 void resume(EmulatorHelper e)throws Exception{long sp=e.readRegister("ESP").longValue(),ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int s=0;s<256;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{int free=s%66,busy=s/66%2,mp=s/132;byte[]u=new byte[192],b=new byte[88],w=new byte[44],g=new byte[100],jobs=new byte[1536],header=new byte[12];for(int i=0;i<u.length;i++)u[i]=(byte)(s*17+i*7+19);for(int i=0;i<b.length;i++)b[i]=(byte)(s*19+i*11+23);for(int i=0;i<w.length;i++)w[i]=(byte)(s*23+i*13+29);for(int i=0;i<g.length;i++)g[i]=(byte)(s*29+i*17+31);for(int slot=0;slot<64;slot++){for(int i=0;i<24;i++)jobs[slot*24+i]=(byte)(s*31+slot*19+i*23+37);set(jobs,slot*24,4,slot==free?0:H);}for(int i=0;i<12;i++)header[i]=(byte)(s*37+i*29+41);set(header,0,2,23);header[11]=(byte)new int[]{0,1,44,127,128,255}[s%6];set(u,8,4,W);set(u,40,4,B);u[0x86]=(byte)255;u[0x96]=0;u[0x8a]&=0xbf;u[0x9a]=(byte)254;u[0x39]=(byte)(s&7);set(b,0,2,400+s*3);set(b,2,2,500+s*5);set(b,0x30,4,H);e.writeMemory(toAddr(U),u);e.writeMemory(toAddr(B),b);e.writeMemory(toAddr(W),w);e.writeMemory(toAddr(G),g);e.writeMemory(toAddr(J),jobs);e.writeMemory(toAddr(H),header);put(e,0x632194,4,G);put(e,0x622dd7,1,1);put(e,0x622dc4,1,mp);put(e,0x4740ac,4,RAND);put(e,S,4,RET);put(e,S+4,4,U);e.writeRegister("ESP",S);e.writeRegister("ECX",U);for(long pc:new long[]{RET,RAND,0x45c5c0,0x452960,0x438740})e.setBreakpoint(toAddr(pc));int crt=0,draw=0,paths=0,ui=0;long uiActor=0,uiIcon=0;if(!e.run(toAddr(0x44fcc0),null,monitor))throw new Exception(e.getLastError());while(e.readRegister("EIP").longValue()!=RET){long pc=e.readRegister("EIP").longValue();if(pc==RAND){crt++;e.writeRegister("EAX",0);}else if(pc==0x45c5c0)draw++;else if(pc==0x452960){paths++;e.writeRegister("EAX",busy);}else if(pc==0x438740){ui++;uiActor=e.readRegister("ECX").longValue()&0xffffffffL;uiIcon=e.readRegister("EDX").longValue()&0xffffffffL;}else throw new Exception("unexpected"+Long.toHexString(pc));resume(e);}out.print("{\"scenario\":"+s+",\"free\":"+free+",\"busy\":"+busy+",\"mp\":"+mp+",\"unit\":\""+hex(e.readMemory(toAddr(U),192))+"\",\"building\":\""+hex(e.readMemory(toAddr(B),88))+"\",\"hardware\":\""+hex(e.readMemory(toAddr(W),44))+"\",\"group\":\""+hex(e.readMemory(toAddr(G),100))+"\",\"jobs\":"+(hash(e.readMemory(toAddr(J),1536))&0xffffffffL)+",\"created\":\""+(free<64?hex(e.readMemory(toAddr(J+free*24),24)):"")+"\",\"header\":\""+hex(e.readMemory(toAddr(H),12))+"\",\"crt\":"+crt+",\"draw\":"+draw+",\"paths\":"+paths+",\"ui\":"+ui+",\"uiActor\":"+uiActor+",\"uiIcon\":"+uiIcon+",\"activeActor\":"+read(e,0x4d18f4,4));out.println("}");}finally{e.dispose();}}}}
}
